function rainbow(text){
  var out=[]; var n=text.length;
  for(var i=0;i<n;i++){ var h=Math.floor((i/Math.max(1,n-1))*360); out.push({ch:text[i], color:'hsl('+h+',85%,62%)'}); }
  return out;
}
var EXPORTS={rainbow:rainbow};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RainbowForgePure = EXPORTS; }
